entries[108996] = { ["name"] = "Alchemischer Katalysator", ["text"] = "Handwerksmaterial\n\"Beschleunigt Reaktionen, die sonst Tausende von Jahren benötigen würden, und ist daher unerlässlich für die Alchemie auf Draenor.\"" }
