entries[109011] = { ["name"] = "Fass mit Schwarzfelspulver", ["text"] = "Questgegenstand\nEinzigartig\n\"Einmal geöffnet, wird dieses Fass hinter Euch stets eine Spur Schwarzfelspulver zurücklassen, bis Ihr wieder bei Thaelin seid.\"" }
