entries[109013] = { ["name"] = "Zügel des Schreckensraben", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen Schreckensraben oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mit dem Hass eines uralten Gottes erfüllt, sind die Schreckensraben die vertrautesten Wächter der Arakkoa.\"\nPromotion:\nWarlords of Draenor Collector's Edition" }
entries[109014] = { ["name"] = "Küken des Schreckens", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man ein Küken des Schreckens beschwört.\nMit Rechtsklick Euer Küken des Schreckens beschwören oder wieder freigeben.\n80 ( 80)" }
