entries[109062] = { ["name"] = "Magierturm, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euren Magierturm auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:" }
entries[109063] = { ["name"] = "Magierturm, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euren Magierturm auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\nLevel 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\nLevel 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Erfolg \"Portalsteine schlagen Portalscheren\".\nVerkaufspreis:" }
entries[109065] = { ["name"] = "Mondsturzgasthaus, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Mondsturzgasthaus auf Stufe 3 ausbauen könnt.\n\nLevel 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\nLevel 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\nLevel 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nBenötigt den Erfolg \"Bleibt ein Weilchen und hört zu\".\nVerkaufspreis:" }
