entries[109120] = { ["name"] = "Glotz' Raketenspalter", ["text"] = "Benutzen: Bringt dauerhaft eine spezielle Vorrichtung an einer Distanzwaffe an, sodass manchmal Euer Tempo 12 Sek. lang um 115 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:" }
entries[109121] = { ["name"] = "Dickes Seil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses Seil ist besonders strapazierfähig.\"" }
entries[109122] = { ["name"] = "Megawattglühfaden", ["text"] = "Benutzen: Bringt dauerhaft eine elektrische Vorrichtung an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 115 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\n\"Alles ist besser unter Strom.\"\nVerkaufspreis:" }
