entries[109137] = { ["name"] = "Sichelfischfleisch", ["text"] = "Handwerksmaterial\n\"Fleisch eines Sichelfischs. Wird in den Gewässern von ganz Draenor geangelt.\"\nVerkaufspreis:" }
entries[109138] = { ["name"] = "Fleisch eines kieferlosen Schleichers", ["text"] = "Handwerksmaterial\n\"Fleisch eines kieferlosen Schleichers. Wird meist in den Gewässern Gorgronds mithilfe eines Köders für Schleicher geangelt.\"\nVerkaufspreis:" }
entries[109139] = { ["name"] = "Fleisch eines dicken Schläfers", ["text"] = "Handwerksmaterial\n\"Fleisch eines dicken Schläfers. Wird meist in den Gewässern Nagrands mithilfe eines Köders für Schläfer geangelt.\"\nVerkaufspreis:" }
entries[109140] = { ["name"] = "Fleisch eines blinden Seestörs", ["text"] = "Handwerksmaterial\n\"Fleisch eines blinden Seestörs. Wird meist in den Gewässern des Schattenmondtals mithilfe eines Köders für Störe geangelt.\"\nVerkaufspreis:" }
entries[109141] = { ["name"] = "Feuerammonittentakel", ["text"] = "Handwerksmaterial\n\"Fleisch eines Feuerammoniten. Wird meist in der Lava des Frostfeuergrats mithilfe eines Köders für Ammoniten geangelt.\"\nVerkaufspreis:" }
entries[109142] = { ["name"] = "Seeskorpionsegment", ["text"] = "Handwerksmaterial\n\"Fleisch eines Seeskorpions. Wird im Ozean um Draenor mithilfe eines Köders für Seeskorpione geangelt.\"\nVerkaufspreis:" }
entries[109143] = { ["name"] = "Fleisch eines Tiefenschluckaals", ["text"] = "Handwerksmaterial\n\"Fleisch eines Tiefenschluckaals, wird meist in den Gewässern der Spitzen von Arak mithilfe eines Köders für Aale geangelt.\"\nVerkaufspreis:" }
entries[109144] = { ["name"] = "Fleisch einer Schwarzwasserpeitschflosse", ["text"] = "Handwerksmaterial\n\"Fleisch einer Schwarzwasserpeitschflosse, wird meist in den Gewässern Taladors mithilfe eines Köders für Peitschflossen geangelt.\"\nVerkaufspreis:" }
entries[109145] = { ["name"] = "Draenisches Fläschchen der Beweglichkeit", ["text"] = "Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
