entries[109148] = { ["name"] = "Draenisches Fläschchen der Stärke", ["text"] = "Benutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109152] = { ["name"] = "Draenisches Fläschchen der Ausdauer", ["text"] = "Benutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109153] = { ["name"] = "Großes draenisches Fläschchen der Beweglichkeit", ["text"] = "Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109155] = { ["name"] = "Großes draenisches Fläschchen der Intelligenz", ["text"] = "Benutzen: Erhöht die Intelligenz 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109156] = { ["name"] = "Großes draenisches Fläschchen der Stärke", ["text"] = "Benutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109160] = { ["name"] = "Großes draenisches Fläschchen der Ausdauer", ["text"] = "Benutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109161] = { ["name"] = "Thaelins Notlösung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt ein Gerät ein, das Ziele der Eisernen Horde \"repariert\". (15 Sek. Abklingzeit)" }
entries[109162] = { ["name"] = "Zauberfoliant der Bindung", ["text"] = "Questgegenstand\n\"Enthält Zaubersprüche und Beschwörungsformeln, mit denen magische Energien an Lebewesen gebunden werden.\"" }
entries[109163] = { ["name"] = "Zauberbuch der Ango'rosh", ["text"] = "Questgegenstand\n\"Achtung: Enthält Zaubersprüche ungebändigter Macht. Unter keinen Umständen verwenden, kontrollieren oder binden.\"" }
entries[109164] = { ["name"] = "Klebrige Teerbombe", ["text"] = "Questgegenstand\nBenutzen: Wirft eine klebrige Teerbombe, um Brüterkäfige in Aguraks Ende zu zerstören.\n\"Die Bombe erst dann einer offenen Flamme aussetzen, wenn sie einsatzbereit ist.\"" }
entries[109167] = { ["name"] = "Findels Plünderang", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Sammelt die Beute von einer Leiche in der Nähe ein. Kann nur in Draenor verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[109168] = { ["name"] = "Eisenschredders Schredder", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nDistanz Schusswaffe\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\n\"Für Ingenieure ein Kunstwerk. Für Jäger ein Werkzeug für die Kunst des Tötens.\"\nVerkaufspreis:" }
entries[109171] = { ["name"] = "Nachtsichtmechbrille", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
entries[109172] = { ["name"] = "Plasmamechbrille", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
entries[109173] = { ["name"] = "Cybergenetische Mechbrille", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
entries[109174] = { ["name"] = "Klingenschutzmechbrille", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
entries[109183] = { ["name"] = "Weltschrumpfer", ["text"] = "Spielzeug\nBenutzen: Schrumpft die gesamte Welt 5 Min. lang oder bis Ihr angreift. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\n\"Übermäßiger Gebrauch kann zu dauerhafter Schrumpfung führen.\"\nVerkaufspreis:" }
entries[109184] = { ["name"] = "Tarner 54", ["text"] = "Benutzen: Umgibt den Anwender mit einem Tarnfeld, solange er stillhält. Kann nicht im Kampf verwendet werden. Nach einer Bewegung bleibt das Feld noch bis zu 6 Sek. lang erhalten.\n\nDer Tarner teilt sich eine Abklingzeit mit allen Tränken außer Heiltränken. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\n\"Unsichtbarkeit ist für Schwächlinge!\"\nVerkaufspreis:" }
entries[109186] = { ["name"] = "Hagras Splitter", ["text"] = "Questgegenstand\n\"Beim Berühren des Splitters habt Ihr das Gefühl, dass Eure Seele von etwas Öligem und Schmutzigem überzogen wird.\"" }
entries[109187] = { ["name"] = "Grogals Splitter", ["text"] = "Questgegenstand\n\"Die Dunkelheit im Innern vibriert, als ob etwas zu entkommen versuchen würde.\"" }
entries[109192] = { ["name"] = "Lichtbringer", ["text"] = "\"Dieser abgenutzte Streitkolben gehörte einst einer Wache Shattraths. Noch immer dringt aus seinem Inneren Licht, auch wenn es langsam zu verblassen scheint.\"\nVerkaufspreis:" }
entries[109196] = { ["name"] = "Vom Kampf gezeichnetes Frostwolfbanner", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Rammt ein vom Kampf gezeichnetes Frostwolfbanner in die Leichname von getöteten Donnerfürsten im Rippenbrecherkriegslager. (2 Sek. Abklingzeit)" }
entries[109197] = { ["name"] = "Auch'naaru", ["text"] = "Questgegenstand\n\"Eines der drei Fragmente des Herzens von Auchindoun.\"" }
entries[109205] = { ["name"] = "Feuriges Herz", ["text"] = "Questgegenstand\n\"Brennt immer noch mit dämonischer Hitze.\"" }
entries[109206] = { ["name"] = "Brennende Fackel", ["text"] = "Questgegenstand\n\"Erste Brandschutzregel: Brennende Fackeln von entzündlichen Objekten fernhalten.\"" }
entries[109217] = { ["name"] = "Draenischer Trank der Beweglichkeit", ["text"] = "Benutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109218] = { ["name"] = "Draenischer Trank der Intelligenz", ["text"] = "Benutzen: Erhöht Eure Intelligenz 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109219] = { ["name"] = "Draenischer Trank der Stärke", ["text"] = "Benutzen: Erhöht Eure Stärke 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109220] = { ["name"] = "Draenischer Trank der Vielseitigkeit", ["text"] = "Benutzen: Erhöht Eure Vielseitigkeit 25 Sek. lang um 31 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109221] = { ["name"] = "Draenischer Trank der Manakanalisierung", ["text"] = "Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 255 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109222] = { ["name"] = "Draenischer Manatrank", ["text"] = "Benutzen: Stellt 1700 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109223] = { ["name"] = "Heiltonikum", ["text"] = "Benutzen: Stellt 3400 Gesundheit wieder her. (5 Min Abklingzeit)\n\"Richtig vorbereitet kann das Gift des Seeskorpions Gesundheit wiederherstellen.\"\nVerkaufspreis:" }
entries[109224] = { ["name"] = "Seelensplitter von Gul'var", ["text"] = "Questgegenstand\nBenutzen: Verbindet die Seelensplitter in der Schmiede von Gul'var, um Gul'dans Seelenfalle herzustellen." }
entries[109225] = { ["name"] = "Gul'dans Seelenfalle", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Ganze fühlt sich nach mehr als die Summe seiner Teile an.\"" }
entries[109226] = { ["name"] = "Draenischer Trank der Verjüngung", ["text"] = "Benutzen: Stellt 3400 Gesundheit und 850 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[109246] = { ["name"] = "Gul'dans Seelenfalle", ["text"] = "Questgegenstand\nBenutzen: Fesselt Gul'dans Seele und setzt ihn gefangen, um ihn zu Erzmagier Khadgar beim Außenposten Sternenfall zurückzubringen. (20 Sek. Abklingzeit)" }
entries[109248] = { ["name"] = "Entwurf einer Belagerungswaffe", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf dem Plan ist eine barbarische und brutale Waffe abgebildet.\"" }
entries[109253] = { ["name"] = "Ultimatives gnomisches Armeemesser", ["text"] = "+10 Fertigkeit in Bergbau von Draenor.\n+10 Fertigkeit in Kräuterkunde von Draenor.\n+10 Fertigkeit in Kürschnerei von Draenor.\n\"Beinhaltet alles erforderliche Handwerkszeug.\"\nVerkaufspreis:" }
entries[109254] = { ["name"] = "Sägewerk, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr das Sägewerk in Eurer Garnison auf Stufe 2 aufwerten könnt.\n\nLevel 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\nLevel 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\nLevel 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:" }
entries[109255] = { ["name"] = "Sägewerk, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr das Sägewerk in Eurer Garnison auf Stufe 3 aufwerten könnt.\n\nLevel 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\nLevel 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\nLevel 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nBenötigt den Erfolg \"Das Sägewerk aufwerten\".\nVerkaufspreis:" }
entries[109256] = { ["name"] = "Ingenieurlabor, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Ingenieurlabor auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:" }
entries[109257] = { ["name"] = "Ingenieurlabor, Stufe 3", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Ingenieurlabor auf Stufe 3 ausbauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:" }
entries[109258] = { ["name"] = "Ingenieurlabor, Stufe 1", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Ingenieurlabor bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:" }
entries[109259] = { ["name"] = "Zauberbuch des Schattenrats", ["text"] = "Questgegenstand\n\"Wenn dieses Buch gefunden wird, bitte den Zauber auf Seite 42 wirken.\"" }
entries[109261] = { ["name"] = "Alchemistenkessel", ["text"] = "Wird beim Aufheben gebunden\n\"Liefert metamorphische Kristalle und alchemische Katalysatoren.\"\n<Zum Öffnen rechtsklicken>" }
entries[109262] = { ["name"] = "Draenischer Stein der Weisen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 4.\nAnlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie von Draenor\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[109557] = { ["name"] = "Mutationsserum", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf Grulk anwenden, um seine Mutantenstärke wiederherzustellen.\"" }
entries[109558] = { ["name"] = "Eine Abhandlung über die Alchemie Draenors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Alchemie von Draenor aus und lehrt Euch einige Rezepte.\nBenötigt Alchemie\n(1)\n\"Eine Einführung in die Geheimnisse der draenischen Alchemie.\"" }
entries[109574] = { ["name"] = "GUMM-E", ["text"] = "Wird bei Benutzung gebunden\nEinzigartig: Gegenstand aus dem Ingenieurlabor (1)\nBenutzen: Stellt einen tragbaren Briefkasten auf, der 5 Min. lang bestehen bleibt. (3 Std. Abklingzeit)\n3 Aufladungen\n\"Dieser spezielle Briefkasten ist normalerweise zu kompliziert für den Durchschnittsbürger, daher besitzt er extragroße Knöpfe und eine Anleitung.\"\nVerkaufspreis:" }
entries[109575] = { ["name"] = "Auch'naaru", ["text"] = "Questgegenstand\n\"Eines der drei Fragmente des Herzens von Auchindoun.\"" }
entries[109576] = { ["name"] = "Mondsturzausgrabung, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Mondsturzausgrabung auf Stufe 2 ausbauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt Mine\nVerkaufspreis:" }
entries[109577] = { ["name"] = "Kräutergarten, Stufe 2", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Kräutergarten in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\nLevel 1\nLässt täglich aus draenischen Samen Kräuter heranwachsen und macht Kräuter im Garten verfügbar.\n\nLevel 2\nErmöglicht es Anhängern mit der Eigenschaft 'Kräuterkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Erhöht außerdem die Menge an Kräutern, die im Garten geerntet werden können und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nPflanzt einen einzigartigen Draenorobstbaum in Eurem Garten, der Nahrungsstärkungseffekte gewährt. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt Kräutergarten\nVerkaufspreis:" }
entries[109578] = { ["name"] = "Angelhütte", ["text"] = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison reparieren könnt.\n\nLevel 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\nLevel 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\nLevel 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nVerkaufspreis:" }
entries[109584] = { ["name"] = "Ogerschreiben", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Oger mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
entries[109585] = { ["name"] = "Verschlüsselte Arakkoanachricht", ["text"] = "\"Schlüsselstein, der archäologische Artefakte der Arakkoa mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:" }
entries[109586] = { ["name"] = "Zerfallende Kartografieaufzeichnungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Archäologie (1)\n\"Lehrt Euch Draenorarchäologie.\"" }
entries[109591] = { ["name"] = "Verliesschlüssel", ["text"] = "Questgegenstand\nEinzigartig\n\"Wenn ein Totenkopf auf dem Griff ist, muss es sich um einen Verliesschlüssel handeln.\"" }
entries[109592] = { ["name"] = "Schlüssel für Corkis Käfig", ["text"] = "Questgegenstand\nBenutzen: Öffnet Corkis Gefängnis.\n\"Dieser schmiedeeiserne Schlüssel wurde schon oft benutzt.\"" }
entries[109599] = { ["name"] = "Neuraler Stummschalter", ["text"] = "Benutzen: Macht Euch immun gegen manche Ärgernisse. Bleibt über den Tod hinaus bestehen Hält 12 Stunden lang an.\n\"Ärgernisse schließen 'Glaubenssprung', Fähigkeiten zur Bedrohungsumleitung und manche Gerätschaften wie den Wechselblaster ein.\"\nVerkaufspreis:" }
entries[109602] = { ["name"] = "Echo of Murmur [TEMP ITEM & SPELL]", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure schreckliche Rübe beschwören oder wieder freigeben.\n80 ( 80)" }
