entries[109644] = { ["name"] = "Walter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: Gegenstand aus dem Ingenieurlabor (1)\nBenutzen: Versucht Walter zusammenzusetzen, den weltweit faulsten Ober und Butler, der 6 Min. lang aushelfen könnte.\n\nWalter kann seinem Erschaffer widerwillig Kontozugang verschaffen. Allen anderen verkauft er einigermaßen schreckliches Essen. (2 Std. Abklingzeit)\n3 Aufladungen\nVerkaufspreis:" }
entries[109645] = { ["name"] = "Schwarzfelszephyrium", ["text"] = "Benutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 475 im Schlossknacken benötigen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:" }
