entries[110116] = { ["name"] = "Fesselschlüssel der Blutschläger", ["text"] = "Questgegenstand\nEinzigartig\n\"Öffnet Owynn Graddocks Fesseln.\"" }
entries[110149] = { ["name"] = "Owynns Streitkolben", ["text"] = "Questgegenstand\n\"Owynns zuverlässiger Schädelspalter.\"" }
entries[110150] = { ["name"] = "Das Herz von Fernus", ["text"] = "Questgegenstand\n\"Das Herz von Fernus ist der Schlüssel zur Vernichtung der Teufelskristalle und gewährt auf der Finsterspitze Zugang zu Gul'dan.\"" }
entries[110226] = { ["name"] = "Dosis Lauerergift", ["text"] = "Questgegenstand\n\"Ganz frisch.\"" }
entries[110227] = { ["name"] = "Frostblütenblätter", ["text"] = "Questgegenstand\n\"Das Berühren dieser Blätter löst Übelkeit aus.\"" }
entries[110228] = { ["name"] = "Frostsplitter", ["text"] = "Questgegenstand\n\"Dieser Splitter ist so kalt, dass er sich beinahe heiß anfühlt.\"" }
entries[110229] = { ["name"] = "Owynns Rüstung", ["text"] = "Questgegenstand\n\"Eine gut geölte Rüstung, mit der man ungesehen durch die Schatten huschen kann.\"" }
entries[110232] = { ["name"] = "Owynns Dolch", ["text"] = "Questgegenstand\n\"Owynns viel gepriesene Klinge, die ihn auf seinen Reisen durch Azeroth begleitet hat.\"" }
entries[110238] = { ["name"] = "Schwur von Schattenjäger Rala", ["text"] = "Wird beim Aufheben gebunden\n\"Da Ihr den Trollen Euren Wert unter Beweis gestellt habt, wird Schattenjäger Rala auf Vol'jins Befehl hin in Eurer Garnison dienen, so Ihr dies wünscht.\"" }
entries[110240] = { ["name"] = "Riesengroßer Yetibalg", ["text"] = "Questgegenstand\n\"Riecht nach Wildnis... und nach Moschus. Aber vorrangig nach Wildnis.\"" }
entries[110253] = { ["name"] = "Arkonitkristall", ["text"] = "Questgegenstand\n\"Wird verwendet, um alltägliche Gegenstände der Draenei mit Energie zu versorgen.\"" }
entries[110268] = { ["name"] = "Rattenköder", ["text"] = "Questgegenstand\nBenutzen: Mit diesem Köder können Ratten zu den unbemannten Eisenschreddern gelockt werden." }
entries[110270] = { ["name"] = "Phiole voller \"Ogron-Abwehrmittel\"", ["text"] = "Questgegenstand" }
entries[110271] = { ["name"] = "Arkonitpylon", ["text"] = "Questgegenstand\n\"Diese Pylonen versorgen normalerweise die Grabstätten außerhalb Auchindouns mit Energie, doch in Notfällen werden sie auch schon mal zweckentfremdet und versorgen ganze Ortschaften.\"" }
entries[110274] = { ["name"] = "Köder für kieferlose Schleicher", ["text"] = "Einzigartig\nBenutzen: Kieferlose Schleicher schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen in Gorgrond. Seetang ist die Lieblingsnahrung kieferloser Schleicher.\"\nVerkaufspreis:" }
entries[110278] = { ["name"] = "Geschwollener Magen", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[110283] = { ["name"] = "Zermahlene Kieselsteine", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Steine wurden zur besseren Verdauung langsam zermahlen.\"\nVerkaufspreis:" }
entries[110284] = { ["name"] = "Angenagte Hand", ["text"] = "Wird beim Aufheben gebunden\n\"Wem die wohl gehört hat?\"\nVerkaufspreis:" }
entries[110285] = { ["name"] = "Hundesteinbrocken", ["text"] = "Wird beim Aufheben gebunden\n\"So Farbe. Vieles Schimmer. So schwer. Wow!\"\nVerkaufspreis:" }
entries[110286] = { ["name"] = "Pflanzenfasern", ["text"] = "Wird beim Aufheben gebunden\n\"Eine gute Nährstoffquelle.\"\nVerkaufspreis:" }
entries[110287] = { ["name"] = "Sich windender Wurm", ["text"] = "Wird beim Aufheben gebunden\n\"Eklig.\"\nVerkaufspreis:" }
entries[110288] = { ["name"] = "Arens Thermometer", ["text"] = "Questgegenstand\nBenutzen: Lest die Temperatur in der Nähe des zischenden Geysirs im Rauchfelskessel ab. (3 Sek. Abklingzeit)" }
entries[110289] = { ["name"] = "Köder für dicke Schläfer", ["text"] = "Einzigartig\nBenutzen: Dicke Schläfer schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen in Nagrand. Dicke Schläfer finden alles Süße unwiderstehlich.\"\nVerkaufspreis:" }
entries[110290] = { ["name"] = "Köder für blinde Seestöre", ["text"] = "Einzigartig\nBenutzen: Blinde Seestöre schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen im Schattenmondtal. Die Bewegungen der am Boden lebenden Sandkrebse erregen die Aufmerksamkeit blinder Seestöre.\"\nVerkaufspreis:" }
entries[110291] = { ["name"] = "Köder für Feuerammoniten", ["text"] = "Einzigartig\nBenutzen: Feuerammoniten schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen im Frostfeuergrat. Frostfeuerfrüchte sind für die meisten Humanoiden tödlich, doch Feuerammoniten sind ganz wild darauf.\"\nVerkaufspreis:" }
entries[110292] = { ["name"] = "Köder für Seeskorpione", ["text"] = "Einzigartig\nBenutzen: Seeskorpione schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen im Meer. Seeskorpione reißen Seesternen gerne die Beine aus und verschlingen sie einzeln.\"\nVerkaufspreis:" }
entries[110293] = { ["name"] = "Köder für Tiefenschluckaale", ["text"] = "Einzigartig\nBenutzen: Tiefenschluckaale schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n\"Nützlich beim Fischen in den Spitzen von Arak. Froschfische haben eine so seltsame Gestalt, dass nur Schluckaale sie fressen können.\"\nVerkaufspreis:" }
entries[110294] = { ["name"] = "Köder für Schwarzwasserpeitschflossen", ["text"] = "Einzigartig\nBenutzen: Erhöht 10 Min. lang die Chance, Schwarzwasserpeitschflossen zu fangen.\n\"Nützlich beim Fischen in Talador. Sandklaffmuscheln sind die Lieblingsspeise der Schwarzwasserpeitschflossen.\"\nVerkaufspreis:" }
entries[110295] = { ["name"] = "Herz von Gorgorek", ["text"] = "Questgegenstand" }
entries[110313] = { ["name"] = "Wolfsflaum", ["text"] = "Questgegenstand\n\"Riecht nach Wildnis... und nach Moschus. Aber vorrangig nach Wildnis.\"" }
entries[110375] = { ["name"] = "Borgals Totem der Flammenbindung", ["text"] = "Questgegenstand\n\"Es tropft noch immer Lava daran herab.\"" }
entries[110378] = { ["name"] = "Borgals Totem der Geisterbindung", ["text"] = "Questgegenstand\n\"Ihr hört ein leises Flüstern, könnt jedoch nicht verstehen, was gesagt wird.\"" }
entries[110379] = { ["name"] = "Borgals Totem der Wasserbindung", ["text"] = "Questgegenstand\n\"Vom faulen Wasser, das dieses Totem bedeckt, sollte man sich besser fernhalten.\"" }
entries[110380] = { ["name"] = "Borgals Totem der Windbindung", ["text"] = "Questgegenstand\n\"Dem Totem hängt ein übler Geruch an.\"" }
entries[110390] = { ["name"] = "Arkane Essenz", ["text"] = "Questgegenstand\n\"Diese magischen Überreste pulsieren vor arkaner Energie.\"" }
entries[110391] = { ["name"] = "Unbearbeitete Kraftkristalle", ["text"] = "Questgegenstand\n\"Obwohl diese Kristalle roh und unbearbeitet sind, strahlen sie arkane Energie aus.\"" }
entries[110394] = { ["name"] = "Leuchtender Seelensplitter", ["text"] = "Questgegenstand\nBenutzen: Läutert den Geist einer besiegten wahnsinnigen Seele. (3 Sek. Abklingzeit)\n\"Von diesem zarten Kristallsplitter geht ein schwaches Licht aus.\"" }
entries[110418] = { ["name"] = "Kristallriesenherz", ["text"] = "Questgegenstand\n\"Das Herz fühlt sich kalt an und in seinem Innern pocht arkane Energie.\"" }
entries[110424] = { ["name"] = "Wilder Safarihelm", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht die von Kampfhaustieren gewonnene Erfahrung um 20%. (3 Sek. Abklingzeit)\nBenötigt Kampfhaustiertraining\n\"Die Haustierjagd ist eine gefährliche Angelegenheit. Tragt dabei immer Euren Hut.\"\nVerkaufspreis:" }
entries[110425] = { ["name"] = "Gnomischer Feiervollstrecker", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bringt Euch für ein Foto in Pose! (30 Min Abklingzeit)" }
entries[110426] = { ["name"] = "Goblinisches heißes Eisen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versucht, das goblinische heiße Eisen einem verbündeten Spielercharakter zuzuwerfen. Falls er Platz in seinem Rucksack hat, wird er es fangen... vorausgesetzt, Ihr könnt es sicher werfen! (2 Sek. Abklingzeit)\nBenötigt Werterhaltungsgesellschaft des Dampfdruckkartells\n- Wohlwollend\nVerkaufspreis:" }
entries[110427] = { ["name"] = "Safarihelm", ["text"] = "Wird beim Aufheben gebunden\nKopf\nVerkaufspreis:" }
entries[110428] = { ["name"] = "Goblinischer Bodybuilderwettkampf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bringt Eure Muskeln zur Geltung! (30 Min Abklingzeit)" }
entries[110431] = { ["name"] = "Lederwasserball", ["text"] = "Benutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen! (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[110433] = { ["name"] = "Libellenwegelagerer", ["text"] = "Benutzen: Verwandelt Euch 5 Min. lang in einen Sumpfleuchter." }
entries[110436] = { ["name"] = "Eisbärenüberraschung", ["text"] = "Wird beim Aufheben gebunden" }
entries[110437] = { ["name"] = "Kur'ika, Hammer der Vollstreckung", ["text"] = "Questgegenstand\n\"Ruft den rechtschaffenen Zorn des Lichts herab, um jene zu erschlagen, die den Versuch wagen, teuflische Magie zu wirken.\"" }
entries[110438] = { ["name"] = "Haufen Elementarasche", ["text"] = "Questgegenstand\n\"Die Überreste eines Lavaelementars, dessen Magie vollkommen aufgebraucht wurde.\"" }
entries[110447] = { ["name"] = "Rylakgedankenkontrollgerät", ["text"] = "Questgegenstand\nBenutzen: Verwendet dieses Gerät, um die Geister der gedankenkontrollierten Rylaks zu befreien." }
entries[110452] = { ["name"] = "Schattenversiegelte Befehle", ["text"] = "Questgegenstand\n\"Trägt das Zeichen des Schattenrats.\"\n<Zum Lesen rechtsklicken>" }
entries[110453] = { ["name"] = "Thaelins Notizbuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Oh ja, hier sind einige peinliche Kritzeleien drin.\"" }
entries[110459] = { ["name"] = "Mysteriöser Ring", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser kunstvolle Ring ist mit einem aufwendig gestalteten 'V' verziert.\"" }
entries[110468] = { ["name"] = "Ableitungskristall", ["text"] = "Questgegenstand\nBenutzen: Besänftigt bei Verwendung einen rasenden Manaschlinger. Der rasende Manaschlinger muss über weniger als 35% Gesundheit verfügen." }
entries[110469] = { ["name"] = "Mysteriöse Stiefel", ["text"] = "Questgegenstand\nEinzigartig (2)\n\"Diese schönen Schuhe sind mit einem aufwendig gestalteten 'V' verziert.\"" }
entries[110470] = { ["name"] = "Mysteriöser Hut", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser mystische Hut ist mit einem aufwendig gestalteten 'V' verziert.\"" }
entries[110471] = { ["name"] = "Mysteriöser Stab", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser magische Stab fluktuiert zwischen verschiedenen Zeiten und ist deutlich mit dem Buchstaben 'V' gekennzeichnet.\"" }
entries[110490] = { ["name"] = "Larry Bugged Item", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert einen Energiestrahl auf einen anvisierten Magmaelementar ab, dank dem er sich der Kontrolle seiner Herren widersetzen kann." }
entries[110492] = { ["name"] = "Flammengeschliffenes Juwel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Feuert einen Energiestrahl auf einen anvisierten Magmaelementar ab, dank dem er sich der Kontrolle seiner Herren widersetzen kann. (5 Sek. Abklingzeit)" }
entries[110505] = { ["name"] = "Faszinierender Fruchthut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt den Hut auf. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[110506] = { ["name"] = "Schmarotzerseestern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Wirft einen harmlosen Seestern auf das Gesicht eines Freundes." }
entries[110508] = { ["name"] = "\"Duftender\" Pheromonfisch", ["text"] = "Wird beim Aufheben gebunden\nDauer: 1 min\nBenutzen: Bedeckt ein verbündetes Ziel und Euch selbst mit Fischpheromonen, die Eure Angelfertigkeit 5 Min. lang um 5 erhöhen." }
entries[110536] = { ["name"] = "Botenaufzeichnungen", ["text"] = "Wird beim Aufheben gebunden\n\"Die meisten Seiten sind voller Schlamm, doch die letzten paar sind noch lesbar.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[110545] = { ["name"] = "Das Herz von Fernus", ["text"] = "Questgegenstand\nBenutzen: Beschwört das Herz von Fernus, um einen Teufelskristall innerhalb von 5 Metern zu zerstören." }
entries[110557] = { ["name"] = "Stab eines Erzmagiers", ["text"] = "Questgegenstand\nEinzigartig" }
entries[110560] = { ["name"] = "Garnisonsruhestein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt Euch in Eure Garnison zurück. (20 Min Abklingzeit)" }
entries[110570] = { ["name"] = "Zeitplan der Sklavenschiffe", ["text"] = "Questgegenstand\n\"Ein Anlegezeitplan für die Schiffe, die gefangene Frostwölfe transportieren.\"" }
entries[110586] = { ["name"] = "Mysteriöse Blume", ["text"] = "Einzigartig\nSpielzeug\nBenutzen: Der Spielercharakter erhält mysteriöse Blumen. (30 Min Abklingzeit)\n\"Eine mysteriöse Blume von einem mysteriösen Orc.\"" }
entries[110591] = { ["name"] = "Flintlockes Sprenghammer", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 5.\nErhöht Eure Tempowertung um + 4.\nVerkaufspreis:" }
entries[110592] = { ["name"] = "Zurückgelassener Schwarzmarktposten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Gegenstand, der in einer vorangegangenen Auktion versteigert, aber nicht abgeholt wurde. Vorsicht beim Öffnen.\"\n<Zum Öffnen rechtsklicken>" }
entries[110606] = { ["name"] = "Schattenjägergewand", ["text"] = "Questgegenstand\n\"Bwu'ja selbst webte es, während sie mit den Loa Zwiesprache hielt.\"" }
entries[110607] = { ["name"] = "Schattenjägergleve", ["text"] = "Questgegenstand\n\"Doppelt so viele Klingen heißt doppelt so große Gefahr.\"" }
entries[110608] = { ["name"] = "Schattenjägermaske", ["text"] = "Questgegenstand\n\"Die Maske urteilt stumm über alles, was sie erblickt.\"" }
entries[110609] = { ["name"] = "Rohes Tierleder", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kürschnerei ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[110610] = { ["name"] = "Rohe Tierlederfetzen", ["text"] = "Benutzen: Für ein rohes Tierleder werden zehn Einheiten benötigt.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\nVerkaufspreis:" }
entries[110611] = { ["name"] = "Poliertes Leder", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Belastbar und geschmeidig. Wird bei der Lederverarbeitung in Draenor verwendet.\"\nVerkaufspreis:" }
entries[110617] = { ["name"] = "Ring - Hauch des kritischen Trefferwerts", ["text"] = "Benutzen: Einen Ring dauerhaft verzaubern, sodass der kritische Trefferwert um 2 erhöht wird.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
