entries[110661] = { ["name"] = "Gestepptes Sternenglanzleder", ["text"] = "Handwerksmaterial\n\"Mit den Ranken von Sternenblumen zusammengenähte Sternenglanzlederstücke. Vielseitig verwendbar.\"\nVerkaufspreis:" }
entries[110664] = { ["name"] = "Sklavenschlüssel der Blutschläger", ["text"] = "Questgegenstand\nEinzigartig\n\"Öffnet Bwu'jas Fesseln.\"" }
entries[110667] = { ["name"] = "Tränenverschmierter Brief", ["text"] = "Wird beim Aufheben gebunden\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[110672] = { ["name"] = "Zauberfoliant der Vier Winde", ["text"] = "Wird an Kriegsmeute gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch die Weisheit der Vier Winde, wodurch Ihr in Pandaria fliegen könnt. Der Foliant wird nach dem Lesen verbraucht.\nGestattet es Euch, in Pandaria fliegende Reittiere zu nutzen.\nBenötigt Reiten (225)" }
entries[110678] = { ["name"] = "Gürteltasche mit Dunkelmond-Gewinnlosen", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält mehrere hundert Dunkelmond-Gewinnlose.\"\n<Zum Öffnen rechtsklicken>" }
entries[110682] = { ["name"] = "Waffe - Mal des Donnerfürsten", ["text"] = "Benutzen: Eine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal Euer kritischer Trefferwert 6 Sek. lang um 77 erhöht wird. Wenn der Effekt aktiv ist, können kritische Heilungen und Angriffe die Dauer verlängern.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nVerkaufspreis:" }
entries[110683] = { ["name"] = "Sha'tari", ["text"] = "Questgegenstand\nEinzigartig\n\"Eines der drei Fragmente des Herzens von Auchindoun.\"" }
entries[110684] = { ["name"] = "Essensreste", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Restchen beschwört.\nBeschwört Kleiner Essensrest oder gibt ihn wieder frei.\n80 ( 80)" }
entries[110685] = { ["name"] = "Sack of Draenor Herbs (TEMP)", ["text"] = "Wird beim Aufheben gebunden\n\"Standing in for sources of herbs that aren't in yet.\"\n<Zum Öffnen rechtsklicken>" }
entries[110686] = { ["name"] = "Heulender Schneewehenring", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+2 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[110687] = { ["name"] = "Ogerbauchring", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+2 Stärke\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nVerkaufspreis:" }
entries[110688] = { ["name"] = "Augurensiegelring des Frostfeuergrats", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+2 Intelligenz\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 3 Vielseitigkeit\nVerkaufspreis:" }
entries[110689] = { ["name"] = "Eisgebundene Frostsängeraxt", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+13 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 2 Vielseitigkeit\nHaltbarkeit 90 / 90\n\"Fühlt sich immer kalt an.\"\nVerkaufspreis:" }
entries[110714] = { ["name"] = "Saberonklaue", ["text"] = "Questgegenstand\n\"Eine erschreckend große Klaue, die bis vor Kurzem Bestandteil eines erschreckend großen Saberon war.\"" }
entries[110719] = { ["name"] = "Gestohlene Waren", ["text"] = "Questgegenstand\n\"Waren und Vorräte von Karawanen, die für die Händler des Rings der Prüfung bestimmt sind.\"" }
entries[110721] = { ["name"] = "Monstermöhre", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure Monstermöhre beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[110723] = { ["name"] = "Fläschchen Krötensaft", ["text"] = "Questgegenstand\n\"Es leuchtet.\"" }
entries[110724] = { ["name"] = "Mulvericks Dienstangebot", ["text"] = "Wird beim Aufheben gebunden\n\"Mulverick, ein Meister des Windes und des Krieges, ist einer der wenigen Orcs des Frostwolfklans, der das Rylakreiten beherrscht.\"" }
entries[110742] = { ["name"] = "Handaxt", ["text"] = "Questgegenstand\n\"Das ist keine Axt, die in der Hand gehalten wird, sondern eine Axt, die die Hand ersetzt.\"" }
entries[110761] = { ["name"] = "Immerseus' kristallenes Auge", ["text"] = "Wird beim Aufheben gebunden\nHals\n+2 Beweglichkeit\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:" }
entries[110784] = { ["name"] = "Dreizack der verderbten Wasser", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n10 - 14 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+3 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 3.\n\nPrismatischer Sockel\nSockelbonus: + 2 Beweglichkeit\n\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[110785] = { ["name"] = "Eingeschlossene Essenz von Immerseus", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n5 - 7 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+1 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nPrismatischer Sockel\nSockelbonus: + 2 Stärke\n\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[110799] = { ["name"] = "Frostwirbelfokus", ["text"] = "Questgegenstand\nBenutzen: Lässt einen Wirbel aus Frostmagie los und löscht damit die Flammen in der Nähe." }
