entries[111308] = { ["name"] = "Frosteisenbarren", ["text"] = "Questgegenstand\n\"Kann wahrscheinlich nur mit gut gefütterten Handschuhen getragen werden.\"" }
entries[111322] = { ["name"] = "Pulsierende Pustel", ["text"] = "Questgegenstand\n\"Pulsiert vor arkaner Energie, selbst wenn sie vom Körper entfernt wurde.\"" }
entries[111348] = { ["name"] = "Uralte Rinde", ["text"] = "Questgegenstand\n\"Sehr leicht, doch erstaunlich schwer von den schlummernden Beschützern zu trennen.\"" }
entries[111349] = { ["name"] = "Eine Abhandlung über den Bergbau auf Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch im Bergbau von Draenor aus.\nBenötigt Bergbau (1)\n\"Ein Überblick über die Eigenschaften der wertvollen Mineralien Draenors und ihrer Abbaumethoden.\"" }
entries[111350] = { ["name"] = "Ein Kompendium der Kräuter Draenors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kräuterkunde von Draenor aus.\nBenötigt Kräuterkunde (1)\n\"Enthält eine Übersicht der magischen Kräuter Draenors und wie man sie erntet.\"" }
entries[111351] = { ["name"] = "Ratgeber zum Kürschnern auf Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kürschnerei von Draenor aus.\nBenötigt Kürschnerei (1)\n\"Wie man Draenors Tiere häutet.\"" }
entries[111356] = { ["name"] = "Anglerhandbuch für Draenor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Angelkunst von Draenor aus.\nBenötigt Angeln (1)\n\"Ein Überblick über Draenors Fische und wie man sie fängt.\"" }
entries[111357] = { ["name"] = "Mörserschützenpfeife", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört die Unterstützung eines Zwergenmörseringenieurs, der Gegner in der Nähe angreift. Nach 30 Sek. verschwindet der Ingenieur.\n\"Am hinteren Ende ist eine kleine Bombe eingraviert.\"\nVerkaufspreis:" }
entries[111364] = { ["name"] = "Erste Hilfe auf Draenor", ["text"] = "Einzigartig\n\"Die in diesem Buch beschriebenen Methoden sind veraltet.\"\nVerkaufspreis:" }
entries[111366] = { ["name"] = "Getriebefederteile", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Diese Teile sind unglaublich anpassbar und von Ingenieuren bei Reparaturen hochgeschätzt.\"\nVerkaufspreis:" }
entries[111387] = { ["name"] = "Kochen auf Draenor leicht gemacht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kochkunst von Draenor aus und lehrt Euch einige Rezepte.\nBenötigt Kochkunst (1)\n\"Lehrt Euch Draenorkochkunst und ein paar einfache Rezepte.\"" }
entries[111402] = { ["name"] = "Mechanischer Axtschnabel", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nBeschwört Euren mechanischen Tukan oder gibt ihn wieder frei.\n80 ( 80)\nVerkaufspreis:" }
entries[111403] = { ["name"] = "Alchemistenkessel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert einen Alchemistenkessel.\n\"Das blubbernde Gebräu enthält metamorphische Kristalle und alchemische Katalysatoren. Manchmal geht allerdings etwas furchtbar schief.\"" }
entries[111406] = { ["name"] = "Sack of Draenor Ore (TEMP)", ["text"] = "Wird beim Aufheben gebunden\n\"Standing in for sources of ore that aren't in yet.\"\n<Zum Öffnen rechtsklicken>" }
