entries[111415] = { ["name"] = "Knochenbeißermesser", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n3 - 6 Schaden Geschwindigkeit 1.80\n(2.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
