entries[111475] = { ["name"] = "Prüglers Schlagstock", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n10 - 13 Schaden Geschwindigkeit 3.60\n(3.2 Schaden pro Sekunde)\n+4 Stärke\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
