entries[111477] = { ["name"] = "Yagas Trophäengürtel", ["text"] = "Wird beim Aufheben gebunden\nTaille Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\nErhöht Eure Tempowertung um + 3.\nErhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 50 / 50\n\"Behängt mit den Zähnen, Hauern und Ohren ihrer gefallenen Feinde.\"\nVerkaufspreis:" }
entries[111478] = { ["name"] = "Gorensplitter", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Diese abgesonderten Kristalle sind rasiermesserscharf.\"" }
entries[111484] = { ["name"] = "Kalter Hauer", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n4 - 8 Schaden Geschwindigkeit 2.60\n(2.3 Schaden pro Sekunde)\n+2 [Beweglichkeit oder Stärke]\n+3 Ausdauer\nHaltbarkeit 90 / 90\nAnlegen: Eure Angriffe haben eine Chance, eine Attacke mit Frostschaden auszulösen, die 24 Schaden verursacht. (Procchance: 15%, 1.417Min. Abklingzeit)\nVerkaufspreis:" }
entries[111485] = { ["name"] = "Verwitterte Flügelklingen", ["text"] = "Questgegenstand\n\"Verziert und dennoch zweckmäßig. Ideale Klingen für einen Anführer, der Seite an Seite mit seinen Untergebenen kämpft.\"" }
entries[111490] = { ["name"] = "Glutrachens lodernde Klaue", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+13 Intelligenz\n+3 Ausdauer\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 65 / 65\nAnlegen: Eure Angriffe haben eine Chance, 28 Feuerschaden zu verursachen. (Procchance: 15%, 1.417Min. Abklingzeit)\nVerkaufspreis:" }
entries[111522] = { ["name"] = "Tikari & K.A.G.O", ["text"] = "Benutzen: Ein außergewöhnliches alkoholisches Getränk.\n\"Ein importierter Trollrum, wunderbar gemixt mit Kiwi, Apfel, Gelb Nr. 42 und Orange.\"\nVerkaufspreis:" }
entries[111524] = { ["name"] = "Zerlumpte Maske", ["text"] = "Questgegenstand\n\"Eine einfache Maske, die nicht zur Verhüllung des Gesichtes, sondern zum Schutz vor den Elementen konzipiert ist. Wer mit Flügeln kämpft, wirbelt viel Staub auf.\"" }
